"use strict";(self.webpackChunk_N_E=self.webpackChunk_N_E||[]).push([[4793],{3060:(i,a,e)=>{e.d(a,{$W:()=>u,DB:()=>t,Dv:()=>s,Fr:()=>r,Rt:()=>o,gi:()=>n});let s={h1:"SEO paslaugos",lead:"SEO paslaugos – tai svetainės optimizacija paieškos sistemoms (Google, Bing ir kt.), kurios tikslas, kad Jūsų svetainę rastų žmonės, ieškantys Jūsų paslaugų ar prekių, o tas srautas virstų užklausomis ir pardavimais.",about:"Esame Market Rats – SEO agentūra, nuo 2010 metų kurianti ir įgyvendinanti ilgalaikes organinio augimo strategijas, apimančias visą organinio augimo procesą – nuo esamos situacijos analizės ir augimo galimybių identifikavimo iki techninės SEO optimizacijos, turinio plėtros, autoriteto stiprinimo ir nuolatinio rezultatų gerinimo. Padedame verslams sukurti tvirtą organinio srauto augimo pagrindą ir užtikrinti nuoseklų svetainės matomumo didėjimą paieškos sistemose. Dirbame su verslais, kurie nori ne tik geresnių pozicijų paieškoje, bet ir realios grąžos iš organinio srauto. Mūsų komanda dirba ir turi patirties su e. prekybos, B2B, B2C, paslaugų, informacinėmis, naujienų, SaaS, daugiakalbėmis ir kt. svetainėmis Lietuvoje bei užsienio rinkose.",priceLine:"SEO kaina prasideda nuo 300 €/mėn ir priklauso nuo projekto apimties, konkurencijos bei verslo tikslų.",priceLink:{label:"SEO paslaugos kaina",href:"#kaina"},ctaLine:"Jei ieškote partnerio, kuris SEO procesą grįstų duomenimis, aiškia strategija ir pamatuojamais rezultatais, susisiekite su mumis ir aptarkime jūsų galimybes augti organinėje paieškoje."},t=[{id:"kaina",n:"01",short:"Kaina",label:"SEO paslaugos kaina"},{id:"kam-aktualu",n:"02",short:"Kam aktualu",label:"Kam aktualūs SEO sprendimai?"},{id:"kodel",n:"03",short:"Kodėl mes",label:"Kodėl verta rinktis Market Rats?"},{id:"kas-yra-seo",n:"04",short:"Kas yra SEO",label:"Kas yra SEO?"},{id:"kas-sudaro",n:"05",short:"Sudedamosios",label:"Kas sudaro SEO optimizaciją?"},{id:"duk",n:"06",short:"DUK",label:"Dažniausiai užduodami klausimai"},{id:"kontaktai",n:"07",short:"Kontaktai",label:"Susisiekite"}],r={title:"Kam aktualūs SEO sprendimai?",intro:"Profesionalios SEO paslaugos aktualios visiems verslams ir projektams, kurių potencialūs klientai ieško informacijos, produktų ar paslaugų internete. Jei Jūsų auditorija naudoja Google ar kitas paieškos sistemas sprendimams priimti, SEO gali padėti pasiekti ją būtent tuo metu, kai atsiranda poreikis.",lead:"SEO sprendimai dažniausiai taikomi:",outro:"Nepriklausomai nuo verslo modelio, pagrindinis kriterijus išlieka tas pats – ar Jūsų potencialūs klientai ieško su Jūsų veikla susijusios informacijos internete. Jei paklausa egzistuoja, SEO dažniausiai yra vienas efektyviausių ilgalaikio augimo kanalų."},o=[{key:"b2b",title:"B2B verslams",text:"Padedame B2B įmonėms didinti matomumą pagal komercinius ir informacinius raktažodžius, pritraukti potencialius klientus bei generuoti užklausas iš organinės paieškos."},{key:"b2c",title:"B2C verslams",text:"SEO leidžia pasiekti vartotojus, kurie aktyviai ieško konkrečių produktų, paslaugų ar problemų sprendimų, ir nukreipti juos į Jūsų svetainę."},{key:"eshop",title:"Elektroninėms parduotuvėms",text:"E. komercijos projektuose SEO padeda didinti organinį srautą į produktų ir kategorijų puslapius, gerinti pardavimų rezultatus ir mažinti priklausomybę nuo mokamos reklamos."},{key:"paslaugos",title:"Paslaugų svetainėms",text:"SEO ypač efektyvus verslams, kurie konkuruoja vietinėje ar nacionalinėje rinkoje ir nori pritraukti daugiau užklausų bei klientų."},{key:"info",title:"Informaciniams portalams ir turinio projektams",text:"Kokybiškai optimizuotas turinys leidžia pritraukti tikslinį lankytojų srautą, stiprinti prekės ženklo autoritetą ir kurti ilgalaikę organinio augimo strategiją."},{key:"naujienos",title:"Naujienų portalams",text:"SEO padeda didinti straipsnių matomumą paieškos sistemose, pritraukti daugiau skaitytojų ir efektyviau išnaudoti kuriamą turinį."},{key:"affiliate",title:"Affiliate (liet. partnerystės) projektams",text:"Paieškos sistemų optimizacija yra vienas svarbiausių kanalų partnerystės projektams, siekiantiems generuoti tikslinį srautą ir didinti pajamas iš rekomendacijų."}],n=[{key:"patirtis",title:"Patirtis ir mastas",bullets:["SEO paslaugas teikiame **nuo 2010 m.** – esame viena pirmųjų ir bene didžiausia specializuota SEO agentūra Lietuvoje (per **95 % pajamų iš SEO** paslaugų).","Patirtis su **300+ klientų, 500+ projektų** maždaug **40 šalių**.","**Vidutinė bendradarbiavimo trukmė – 2,5 metų**; specializuojamės nuolatinėje SEO priežiūroje, o ne vienkartiniuose darbuose.","Platus partnerių tinklas: **~100 patikrintų** rašytojų, programuotojų, kūrybininkų, IT ir reklamos įmonių."]},{key:"rezultatas",title:"Mūsų principas – grynas rezultatas",bullets:["Mažiau grožio ir lozungų, daugiau **pamatuojamos grąžos** išleistam eurui.","Esame **SEO architektai, o ne darbininkai**: projektuojame SEO sistemą ir strategiją, o ne vykdome šabloninį algoritmą.","Dirbame pagal **Pareto principą (80/20)** – pirmiausia darbai, turintys didžiausią įtaką rezultatui.","Žiūrime į svetainę kaip į visumą ir **neribojame raktažodžių kiekio** – tai ypač padidina efektyvumą didelės apimties projektuose."]},{key:"skaidrumas",title:"Skaidrumas ir sąžiningumas",bullets:["Nebijome klysti: taikome principą **eksperimentas → analizė → metodų koregavimas**; nesivaikome SEO madų, ieškome veiksmingiausių metodų.","**Netaikome jokio antkainio** trečiųjų šalių išlaidoms (turinys, talpinimai, Ads ir kt.).","Nebijome pasakyti **„Ne“**: jei matome, kad SEO neatsipirks ar tikslai nerealistiški – perspėjame iš anksto.","Neteikiame konkurentų juodinimo ar kenkimo paslaugų – dirbame tik su nauda lankytojui ir savininkui, kad rezultatai būtų **tvarūs ir atsparūs Google algoritmų pokyčiams**."]},{key:"lankstumas",title:"Lankstumas ir bendradarbiavimas",bullets:["Kiekvienam projektui rengiame **individualų pasiūlymą** – „kas tinka visiems, netinka niekam“.","Galimi skirtingi **atsiskaitymo modeliai**: pagal pozicijas, pagal srautą arba (dalinai) nuo rezultatų – srauto, pozicijų ar konversijų.","Galime pasiūlyti **bendro projekto modelį**, kai abi šalys dalijasi atsakomybe ir uždarbiu.","Padedame augti greitai: apskaičiuojame projekto padėtį rinkoje ir **resursus, reikalingus pasivyti ar aplenkti konkurentus**."]}],u=[{key:"auditas",title:"SEO auditas ir strategija",text:"SEO darbai prasideda nuo esamos situacijos įvertinimo. Atliekame raktažodžių tyrimą, analizuojame paieškos paklausą, konkurentų veiksmus, svetainės būklę ir augimo potencialą. Remiantis surinktais duomenimis formuojama SEO strategija, nustatomi tikslai, prioritetai ir veiksmų planas.",tools:["Ahrefs","Google Keyword Planner","Google Trends","Search Console","SimilarWeb","Answer The Public","ChatGPT"],href:"/seo-paslaugos/svetainems/seo-auditas"},{key:"vidinis",title:"Vidinis SEO",text:"Vidinis SEO apima visus optimizacijos darbus pačioje svetainėje. Tvarkoma puslapių struktūra, vidinis nuorodų tinklas, meta duomenys, turinio išdėstymas ir kiti elementai, kurie padeda paieškos sistemoms geriau suprasti svetainės turinį ir svarbiausius puslapius.",tools:["Screaming Frog","Ahrefs","Search Console","Google Analytics 4","ChatGPT"],href:"/seo-paslaugos/svetainems/vidinis-seo"},{key:"techninis",title:"Techninis SEO",text:"Techninis SEO užtikrina, kad svetainė būtų lengvai pasiekiama ir tinkamai suprantama paieškos sistemų robotams. Vertinama indeksacija, svetainės greitis, mobilioji versija, URL struktūra, techninės klaidos, struktūrizuoti duomenys ir kiti veiksniai, turintys įtakos matomumui paieškoje.",tools:["Ahrefs","Screaming Frog","Google Search Console","PageSpeed Insights","Google Tag Manager","Tag Assistant","Linko.app"],href:"/seo-paslaugos/svetainems/techninis-seo"},{key:"isorinis",title:"Išorinis SEO",text:"Išorinis SEO orientuotas į svetainės autoriteto stiprinimą. Tam naudojamos kokybiškos atgalinės nuorodos, partnerystės, sklaida teminiuose šaltiniuose, skaitmeninis PR ir kitos priemonės, padedančios didinti svetainės patikimumą paieškos sistemų akyse.",tools:["Ahrefs","MOZ","SimilarWeb","Search Console","LinkVizor"],href:"/seo-paslaugos/svetainems/isorinis-seo"},{key:"lokalus",title:"Lokalus ir tarptautinis SEO",text:"SEO strategija pritaikoma pagal verslo veiklos geografiją. Lokalus SEO padeda pritraukti klientus konkrečiame mieste ar regione, o tarptautinis SEO skirtas verslams, veikiantiems keliose rinkose ir skirtingomis kalbomis.",tools:["Ahrefs","DeepL","Search Console"],href:"/seo-paslaugos/svetainems/lokalus-seo"},{key:"geo",title:"GEO / AEO (angl. Generative / Answer Engine Optimization)",text:"Šiuolaikinė paieška vis dažniau vyksta ne tik per tradicinius paieškos rezultatus, bet ir per dirbtinio intelekto generuojamus atsakymus. GEO optimizacija orientuota į tai, kad svetainės turinys būtų suprantamas ir cituojamas AI sistemų, tokių kaip ChatGPT, Google AI Overview, Gemini ar Perplexity.",tools:["ChatGPT","Ahrefs","AISearch"],href:"/ai-seo-paslaugos"},{key:"ataskaitos",title:"Rezultatų stebėjimas ir duomenimis grįsti sprendimai",text:"SEO yra nuolatinis procesas, todėl svarbu stebėti rezultatus ir priimti sprendimus remiantis duomenimis. Reguliariai analizuojame pozicijų pokyčius, organinį srautą, konversijas, konkurentų veiksmus ir identifikuojame naujas augimo galimybes.",tools:["Google Analytics 4","Google Search Console","Ahrefs"],href:"/seo-paslaugos/svetainems/rezultatu-matavimas"}];s.ctaLine},6242:(i,a,e)=>{e.r(a),e.d(a,{default:()=>r});var s=e(4812),t=e(7296);function r(i){let{children:a,className:e="",delay:r=0,as:o="div"}=i,n=(0,t.useRef)(null);return(0,t.useEffect)(()=>{let i=n.current;if(!i)return;let a=new IntersectionObserver(e=>{let[s]=e;s.isIntersecting&&(i.classList.add("in"),a.disconnect())},{threshold:.05,rootMargin:"0px 0px 15% 0px"});return a.observe(i),()=>a.disconnect()},[]),(0,s.jsx)(o,{ref:n,className:"reveal ".concat(e),style:r?{transitionDelay:"".concat(r,"ms")}:void 0,children:a})}}}]);